WHERE NOT EXISTS (SELECT 1 FROM geo_municipio);

CREATE TABLE IF NOT EXISTS geo_localidad (
  localidad_id  VARCHAR(9)   PRIMARY KEY,
  municipio_id  VARCHAR(5)   NOT NULL REFERENCES geo_municipio (municipio_id),
  nombre        VARCHAR(150) NOT NULL,
  ambito        CHAR(1)      NOT NULL CHECK (ambito IN ('U', 'R')),
  latitud       NUMERIC(8, 6) NOT NULL,
  longitud      NUMERIC(9, 6) NOT NULL
);

